#!/usr/bin/env python3
"""
apply_multicloud_full_build.py
================================
Completes the multi-cloud build: real Azure (Service Principal) and real
GCP (Service Account) provider support, replacing the earlier Azure/GCP
"coming soon" onboarding tabs entirely. No stubs — credential validation,
resource discovery, console-link generation, and metric catalogs are all
real for both providers, same as AWS.

What this does when you run it:
  1. Backs up and overwrites every changed backend/frontend file below.
  2. Fixes a real, pre-existing corruption in .gitignore: an earlier
     `echo "..." >> .gitignore` in PowerShell wrote UTF-16LE text into a
     UTF-8 file, and one of the resulting garbled lines resolves to a bare
     "*" pattern that silently made git ignore ALL new untracked files.
     (Explicit `git add <path>` calls sidestepped this so far, but it was
     a landmine for the next `git add .` or file that isn't added by
     exact path.) This script rewrites .gitignore cleanly in UTF-8,
     preserving every real rule and de-duplicating.
  3. Applies db/migrations/010_provider_credentials_table.sql directly
     against your MySQL DB (idempotent — safe to re-run).

What this does NOT do (separate steps, same as your usual flow):
  - pip install -r requirements.txt   (new Azure/GCP SDK deps)
  - npm install (frontend already has all deps it needs — MetricSelector,
    api.js etc. are all pre-existing; no new npm packages required)
  - python scripts/seed_multicloud_metric_catalog.py  (seeds Azure/GCP
    metric_catalog rows — run this once after pip install)

Usage:
    python apply_multicloud_full_build.py --dry-run
    python apply_multicloud_full_build.py

Run from the project root: D:/Project/monitoring-tool/monitoring-hub-V5-multi-cloud
"""
import argparse
import base64
import os
import shutil
