BACKUP_SUFFIX = ".bak.pre-multicloud-full-build"


def write_file(root: Path, relpath: str, content: bytes, is_new: bool, dry_run: bool) -> str:
    target = root / relpath
    if target.exists():
        action = "PATCH"
        if not dry_run:
            shutil.copy2(target, str(target) + BACKUP_SUFFIX)
    else:
        action = "CREATE"
        if not dry_run:
            target.parent.mkdir(parents=True, exist_ok=True)
    if not dry_run:
        target.write_bytes(content)
    return action


def fix_gitignore(root: Path, dry_run: bool):
    """The real bug: a prior PowerShell `>>` append wrote UTF-16LE bytes
    into this UTF-8 file. One resulting line decodes (when git parses the
    file loosely) to a bare '*' — which silently ignores every new
    untracked file that isn't added by explicit path. Rewrite clean."""
    path = root / ".gitignore"
    if not path.exists():
        return "SKIPPED (no .gitignore found)"

    raw = path.read_bytes()
    # Pull every printable ASCII line out regardless of UTF-8/UTF-16
    # interleaving, then dedupe while preserving first-seen order.
    text = raw.decode("utf-8", errors="ignore").replace("\x00", "")
    seen = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line == "*":
            # This is exactly the corrupted line that broke tracking —
            # drop it. (A legitimate bare "*" ignore rule would be
            # senseless in this repo anyway; it would ignore everything.)
            continue
        if line not in seen:
            seen.append(line)

    clean = "\n".join(seen) + "\n"
    if not dry_run:
        shutil.copy2(path, str(path) + BACKUP_SUFFIX)
        path.write_text(clean, encoding="utf-8", newline="\n")
    return f"CLEANED ({len(seen)} unique rules kept, corrupted bare-'*' line removed)"


def apply_migration(root: Path, dry_run: bool):
    sql_path = root / "db" / "migrations" / "010_provider_credentials_table.sql"
    if dry_run:
        return "DRY-RUN (would connect to MySQL and execute this file)"
    try:
        import mysql.connector
    except ImportError:
        return "SKIPPED — mysql-connector-python not installed yet. Run this migration manually later, or re-run this script after `pip install -r requirements.txt`."

    try:
        from dotenv import load_dotenv
        load_dotenv(root / ".env")
    except ImportError:
        pass

    cfg = dict(
        host=os.getenv("DB_HOST", "127.0.0.1"),
        port=int(os.getenv("DB_PORT", 3306)),
        user=os.getenv("DB_USER", "monitor"),
        password=os.getenv("DB_PASSWORD", "root123"),
        database=os.getenv("DB_NAME", "monitoring_hub"),
    )
    try:
        conn = mysql.connector.connect(**cfg)
        cur = conn.cursor()
        sql = sql_path.read_text(encoding="utf-8")
        for statement in [s.strip() for s in sql.split(";") if s.strip() and not s.strip().startswith("--")]:
            cur.execute(statement)
        conn.commit()
        cur.close()
        conn.close()
        return "APPLIED (provider_credentials table created/verified)"
    except Exception as e:
        return f"FAILED — {e}\n  Apply manually: mysql -u{cfg['user']} -p {cfg['database']} < db/migrations/010_provider_credentials_table.sql"


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    root = Path.cwd()
    if not (root / "app").exists() or not (root / "frontend").exists():
        print("ERROR: run this from the project root (folder containing app/ and frontend/)")
        sys.exit(1)

    print(f"{'DRY RUN — ' if args.dry_run else ''}Applying multi-cloud full build in {root}\n")

    print("── Files ──")
    for relpath, meta in FILES.items():
        content = base64.b64decode(meta["b64"])
        action = write_file(root, relpath, content, meta["new"], args.dry_run)
        print(f"  [{action:6}] {relpath}  ({len(content)} bytes)")

    print("\n── .gitignore encoding fix ──")
    print(f"  {fix_gitignore(root, args.dry_run)}")

    print("\n── DB migration 010_provider_credentials_table.sql ──")
    print(f"  {apply_migration(root, args.dry_run)}")

    print("\nDone." if not args.dry_run else "\nDry run complete — nothing was written.")
    if not args.dry_run:
        print(textwrap_next_steps())


def textwrap_next_steps() -> str:
    return """
Next steps:
  1. pip install -r requirements.txt
  2. python scripts/seed_multicloud_metric_catalog.py
  3. Restart uvicorn
  4. cd frontend; npm run build   (already verified clean in a test copy of this repo)
  5. Onboard an Azure or GCP account from the UI — both tabs are fully live now,
     including real "Test Connection" credential validation before save.

Backups of every overwritten file are alongside the originals, suffixed:
  .bak.pre-multicloud-full-build
"""


if __name__ == "__main__":
    main()
